/* ==========================================================
   MoodTube theme: Rose Vinyl  (theme format v2)
   Pixel-pink retro player.
   Art lives in assets/*.svg (vinyl, tonearm, star) and is inlined by
   build.mjs into rose-player.json.
   Import rose-player.json in MoodTube settings -> Custom theme.
   ========================================================== */

@import url('https://fonts.googleapis.com/css2?family=Pixelify+Sans:wght@400..700&display=swap');

@keyframes mt-rose-spin { to { transform: rotate(360deg); } }

/* ---------- Palette + slider variables ---------- */
.mt-player, #mt-settings-modal, .mt-fab, .mt-pl-modal {
    --rv-pink-2:   #f3b8c8;
    --rv-edge:     #d98aa0;
    --rv-ink:      #7a3b52;
    --rv-ink-soft: #b0697f;
    --rv-hot:      #e0607e;

    --mt-slider-track: #f9dbe3;
    --mt-slider-track-height: 8px;
    --mt-slider-track-radius: 4px;
    --mt-slider-progress: var(--rv-hot);
    --mt-slider-thumb-size: 20px;
    --mt-slider-thumb-bg: url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2016%2016%27%3E%3Cpath%20fill%3D%27%23f48fb1%27%20stroke%3D%27%237a3b52%27%20stroke-width%3D%271.2%27%20stroke-linejoin%3D%27miter%27%20d%3D%27M8%201l2.1%204.4%204.9.6-3.6%203.3%201%204.8L8%2011.6%203.6%2014.1l1-4.8L1%206l4.9-.6z%27%2F%3E%3C%2Fsvg%3E") center / contain no-repeat;
    --mt-slider-thumb-bg-hover: url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2016%2016%27%3E%3Cpath%20fill%3D%27%23f48fb1%27%20stroke%3D%27%237a3b52%27%20stroke-width%3D%271.2%27%20stroke-linejoin%3D%27miter%27%20d%3D%27M8%201l2.1%204.4%204.9.6-3.6%203.3%201%204.8L8%2011.6%203.6%2014.1l1-4.8L1%206l4.9-.6z%27%2F%3E%3C%2Fsvg%3E") center / contain no-repeat;
    --mt-slider-thumb-border: none;
    --mt-slider-thumb-radius: 0;
    --mt-slider-thumb-shadow: none;
}

/* The extension already resets text-shadow in the player and FAB; the settings modal is ours to fix */
#mt-settings-modal, #mt-settings-modal *, .mt-pl-modal, .mt-pl-modal * { text-shadow: none; }

/* ---------- Window frame ---------- */
.mt-player {
    padding: 40px 14px 16px;
    background: linear-gradient(180deg, #fbdde5 0%, var(--rv-pink-2) 100%);
    border: 2px solid var(--rv-edge);
    border-radius: 10px;
    color: var(--rv-ink);
    font-family: 'Pixelify Sans', 'Courier New', monospace;
    box-shadow: none;
    backdrop-filter: none; -webkit-backdrop-filter: none;
}
.mt-player * { font-family: inherit; }
.mt-player i { font-family: 'Font Awesome 6 Free', 'Font Awesome 5 Free', FontAwesome; }
/* Title bar: the header is flattened so title and status can be placed freely */
.mt-player:not(.moodtube-row-layout) .mt-player-header { display: contents; }
.mt-player-header { right: 96px; } /* room for three window buttons: search, settings, close */
.mt-player:not(.moodtube-row-layout) .mt-player-header-title {
    position: absolute; top: 11px; left: 14px; z-index: 6;
}
.mt-player-header-title {
    color: var(--rv-ink); font-size: 14px; font-weight: 400; letter-spacing: 0.5px;
}
.mt-player-status { color: var(--rv-ink-soft); opacity: 1; }
.mt-player:not(.moodtube-row-layout) .mt-player-status {
    position: absolute; z-index: 3; top: 184px; left: 24px; font-size: 10px;
}

/* Window buttons */
.mt-window-btn {
    top: 8px; width: 20px; height: 20px; box-sizing: border-box;
    display: flex; align-items: center; justify-content: center;
    font-size: 11px; color: var(--rv-hot);
    background: #fde9ee; border: 1px solid var(--rv-edge); border-radius: 3px;
}
.mt-btn-search   { right: 64px; }
.mt-btn-settings { right: 38px; }
.mt-btn-close    { right: 12px; }

/* ---------- Art panel: top-down turntable ---------- */
.mt-player-body { gap: 8px; justify-content: flex-start; }

.mt-player:not(.moodtube-row-layout) .mt-cover {
    /* fixed-size panel centered in the window, so the art never stretches */
    width: 222px; max-width: 100%; height: 130px; box-sizing: border-box; align-self: center;
    border-radius: 6px; border: 1px solid var(--rv-edge);
    background: #f8e4ea; box-shadow: none;
}
/* Record + platter (images.cover_bg) under the label, tonearm (images.cover) on top */
.mt-player:not(.moodtube-row-layout) .mt-slot-cover-bg { background-size: 100% 100%; }
.mt-player:not(.moodtube-row-layout) .mt-slot-cover {
    z-index: 3; background-size: 100% 100%;
    transform-origin: 86.5% 15.4%;
    transform: rotate(-26deg);
    transition: transform 0.6s ease-in-out;
}
.mt-player.mt-is-playing:not(.moodtube-row-layout) .mt-slot-cover { transform: rotate(0deg); }

/* Album art is the record label */
.mt-player:not(.moodtube-row-layout) .mt-cover-img {
    width: 40px; height: 40px; flex: none;
    background: #fde9ee;
    box-shadow: none;
    position: relative; z-index: 2;
}
.mt-player.mt-is-playing .mt-cover-img { animation: mt-rose-spin 4s linear infinite; }
.mt-player:not(.moodtube-row-layout) .mt-cover-hole {
    width: 6px; height: 6px; z-index: 2;
    background: #f8e4ea; border: 1px solid #121212;
}

/* ---------- Now playing ---------- */
.mt-player:not(.moodtube-row-layout) .mt-track-info {
    align-items: flex-start; text-align: left;
    background: #fde9ee; border: 1px solid var(--rv-edge); border-radius: 6px;
    padding: 16px 26px 5px 8px;
}
.mt-track-title { color: var(--rv-ink); font-size: 15px; font-weight: 600; margin-bottom: 0; }
.mt-track-subtitle { color: var(--rv-ink-soft); font-size: 10px; font-weight: 400; }
.mt-btn-favorite { color: var(--rv-hot); font-size: 14px; right: 7px; top: 6px; }

/* ---------- Progress + volume ---------- */
.mt-progress { margin-top: 0; color: var(--rv-ink-soft); font-size: 10px; }
.mt-volume { width: 100%; }
.mt-volume-icon { color: var(--rv-hot); }

/* ---------- Control buttons ---------- */
.mt-controls { gap: 6px; }
.mt-controls > .mt-btn {
    width: 34px; height: 30px; box-sizing: border-box;
    display: flex; align-items: center; justify-content: center;
    font-size: 13px; color: #b64d6f;
    background: #f8c6d3; border: 1px solid var(--rv-edge); border-radius: 7px;
    box-shadow: 0 2px 0 var(--rv-edge);
}
.mt-controls > .mt-btn-play { width: 44px; font-size: 15px; background: #f6aebf; }
.mt-controls > .mt-btn:hover  { transform: translateY(-1px); background: #fddbe4; color: var(--rv-hot); }
.mt-controls > .mt-btn:active { transform: translateY(2px); box-shadow: 0 0 0 var(--rv-edge); }

/* The AI button spins only its inner icon (.mt-btn-icon.fa-spin) - base styles handle it */
.mt-btn-ai.mt-is-busy { color: var(--rv-hot); }

/* ---------- Queue / playlists panels ---------- */
.mt-panel { background: #f8d3dc; padding-top: 42px; }
.mt-panel-title { color: var(--rv-ink); font-size: 11px; }
.mt-panel-close, .mt-panel .mt-btn-accent { color: var(--rv-hot); }

.mt-queue-item { background: #fde9ee; border: 1px solid transparent; border-radius: 6px; }
.mt-queue-item:hover { background: #fddbe4; }
.mt-queue-item.mt-is-current { background: #fde9ee; border-color: var(--rv-hot); }
.mt-queue-thumb { border-radius: 3px; border: 1px solid var(--rv-edge); box-sizing: border-box; }
.mt-queue-thumb.mt-is-empty { background: #f6aebf; }
.mt-queue-title, .mt-queue-item.mt-is-current .mt-queue-title, .mt-playlist-title { color: var(--rv-ink); }
.mt-queue-item.mt-is-blocked .mt-queue-title { color: #b8324f; }
.mt-queue-now, .mt-queue-add { color: var(--rv-hot); }
.mt-queue-dislike { background-color: var(--rv-hot); }
.mt-queue-empty { color: var(--rv-ink-soft); }

.mt-resize-handle i { color: var(--rv-hot); }

/* ---------- Floating button ---------- */
.mt-fab, .mt-fab.mt-fab-docked {
    background: #f8c6d3; border-color: var(--rv-edge, #d98aa0);
    box-shadow: 0 2px 0 #d98aa0; color: #b64d6f;
}

/* ---------- Settings window: colors only (layout and fonts stay the extension's) ---------- */
/* Text colors come from the extension's variables; the rest are plain class overrides. */
#mt-settings-modal, .mt-player, .mt-fab, .mt-pl-modal {
    --mt-text: var(--rv-ink);
    --mt-text-dim: var(--rv-ink-soft);
    --mt-text-on-accent: #ffffff;
}
#mt-settings-modal, .mt-pl-modal {
    --mt-overlay: rgba(122, 59, 82, 0.35);
    --mt-modal-shadow: inset 0 0 0 2px #fff3f6;
    --mt-text-strong: var(--rv-ink);
    --mt-divider: rgba(217, 138, 160, 0.35);
}
#mt-settings-modal .mt-flex-container {
    border: 2px solid var(--rv-edge); border-radius: 10px; backdrop-filter: none;
}
#mt-settings-modal .mt-close { color: var(--rv-hot); }
#mt-settings-modal .mt-content { scrollbar-color: var(--rv-edge) transparent; }
#mt-settings-modal .mt-content::-webkit-scrollbar-thumb { background-color: var(--rv-edge); }
#mt-settings-modal .mt-cat-title:hover { background-color: rgba(224, 96, 126, 0.08); }

#mt-settings-modal .mt-tag { background-color: #fde9ee; border-color: var(--rv-edge); box-shadow: none; }
#mt-settings-modal .mt-genre-tag:hover, #mt-settings-modal .mt-mood-tag:hover, #mt-settings-modal .mt-scenario-tag:hover {
    background-color: #fddbe4; border-color: var(--rv-hot);
}
#mt-settings-modal .mt-genre-tag.active, #mt-settings-modal .mt-mood-tag.active, #mt-settings-modal .mt-scenario-tag.active {
    background-color: var(--rv-hot); border-color: var(--rv-hot); box-shadow: none;
}
#mt-settings-modal .mt-sum-genre, #mt-settings-modal .mt-sum-mood, #mt-settings-modal .mt-sum-scenario { box-shadow: none; }
#mt-settings-modal .mt-btn-test { background: #fde9ee; border-color: var(--rv-edge); }
#mt-settings-modal .mt-btn-test:hover { background: #fddbe4; border-color: var(--rv-hot); }
#mt-settings-modal .mt-subpanel { background: #fde9ee; }

/* ---------- Scrollbars (the tavern's grey ones are replaced everywhere in our UI) ---------- */
.mt-player *, #mt-settings-modal * { scrollbar-width: thin; scrollbar-color: var(--rv-edge) #fde9ee; }
.mt-player ::-webkit-scrollbar, #mt-settings-modal ::-webkit-scrollbar { width: 8px; height: 8px; }
.mt-player ::-webkit-scrollbar-track, #mt-settings-modal ::-webkit-scrollbar-track { background: #fde9ee; border-radius: 4px; }
.mt-player ::-webkit-scrollbar-thumb, #mt-settings-modal ::-webkit-scrollbar-thumb { background: var(--rv-edge); border-radius: 4px; }
.mt-player ::-webkit-scrollbar-thumb:hover, #mt-settings-modal ::-webkit-scrollbar-thumb:hover { background: var(--rv-hot); }

/* ---------- Search panel and playlists (added to the extension later) ---------- */
/* the search panel forces an opaque background from --mt-bg-primary: set it here, no !important */
.mt-panel-search { --mt-bg-primary: #f8d3dc; }
/* the extension paints the search button icon black; use the theme's "text on accent" colour */
#moodtube-search-container #moodtube-search-go { color: var(--mt-text-on-accent, #ffffff) !important; }

.mt-player, .mt-pl-modal {
    --mt-pl-spotify-tab: var(--rv-hot);
    --mt-pl-spotify-tab-text: var(--mt-text-on-accent, #ffffff);
}
.mt-btn-favorite.mt-is-active { color: var(--rv-hot); }
.mt-pl-tabs { background: #fddbe4; }
.mt-pl-tab { color: var(--rv-ink-soft); }
.mt-pl-tool { background: #fde9ee; border-color: var(--rv-edge); color: var(--rv-ink); }
.mt-pl-tool:hover { background: #fddbe4; }
.mt-pl-tool.mt-pl-play { background: var(--rv-hot); border-color: var(--rv-hot); color: var(--mt-text-on-accent, #ffffff); }
.mt-pl-inline-cancel { background: #fddbe4; color: var(--rv-ink); }
.mt-pl-cover-empty { background: #fddbe4; color: var(--rv-ink-soft); }
.mt-pl-modal-box { background: #f8d3dc; border: 2px solid var(--rv-edge); border-radius: 10px; box-shadow: none; }
.mt-pl-modal-track { border-bottom-color: var(--rv-edge); }
.mt-pl-modal-close { color: var(--rv-hot); }
.mt-pl-option { background: #fde9ee; }
.mt-pl-option:hover { background: #fddbe4; }
.mt-pl-option.mt-is-added .mt-pl-option-icon { color: var(--rv-hot); }

/* ---------- Theme catalog in the settings window ---------- */
#mt-settings-modal .mt-catalog-preview { background: #fddbe4; color: var(--rv-ink-soft); }
#mt-settings-modal .mt-catalog-tag { background: #fddbe4; color: var(--rv-ink-soft); }

/* ===== Dock bar (strip under the tavern header) [auto] ===== */
#moodtube-dock {
  font-family: 'Pixelify Sans', 'Courier New', monospace;
  --mt-dock-cover-radius: 50%;
}
#moodtube-dock, #moodtube-dock * { text-shadow: none; }
#moodtube-dock .mt-dock-cover { border-width: 1.5px; }
#moodtube-dock .mt-dock-controls { gap: 6px; }
#moodtube-dock .mt-dock-btn {
  width: 28px; height: 28px; padding: 0; box-sizing: border-box; line-height: 1; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center; border-radius: 50%;
  font-size: 12px; color: var(--mt-text);
  background: color-mix(in srgb, var(--mt-accent) 12%, transparent);
  transform: none; transition: background-color 0.2s;
}
#moodtube-dock .mt-dock-btn:hover { transform: none; color: var(--mt-text); background: color-mix(in srgb, var(--mt-accent) 28%, transparent); }
#moodtube-dock .mt-dock-play {
  width: 34px; height: 34px; font-size: 14px;
  background: var(--mt-accent); color: var(--mt-text-on-accent, #ffffff);
}
#moodtube-dock .mt-dock-play:hover { background: var(--mt-accent-hover, var(--mt-accent)); color: var(--mt-text-on-accent, #ffffff); }
#moodtube-dock .mt-dock-play.fa-play { padding-left: 2px; }
#moodtube-dock .mt-dock-fav, #moodtube-dock .mt-dock-ai, #moodtube-dock .mt-dock-queue { color: var(--mt-text); }
#moodtube-dock .mt-dock-fav.mt-is-active, #moodtube-dock .mt-dock-ai.mt-is-busy { color: var(--mt-accent); }
#moodtube-dock .mt-dock-expand, #moodtube-dock .mt-dock-close { color: var(--mt-text-dim, var(--mt-text)); }
#moodtube-dock .mt-dock-queue.mt-is-open, #moodtube-dock .mt-dock-expand.mt-is-open {
  color: var(--mt-text); text-shadow: none; background: color-mix(in srgb, var(--mt-accent) 30%, transparent);
}
#moodtube-dock .mt-dock-progress { height: 3px; }
@media (max-width: 420px) {
  #moodtube-dock .mt-dock-inner { gap: 6px; padding-left: 8px; padding-right: 8px; }
  #moodtube-dock .mt-dock-controls { gap: 3px; }
  #moodtube-dock .mt-dock-btn { width: 24px; height: 24px; font-size: 11px; }
  #moodtube-dock .mt-dock-play { width: 28px; height: 28px; font-size: 12px; }
}
/* ===== /Dock bar ===== */
/* == lyrics button == the fourth window button, in line with search / settings / close */
.mt-player .mt-lyrics-body { scrollbar-width: none; }
.mt-player .mt-lyrics-body::-webkit-scrollbar { display: none; width: 0; }
/* == /lyrics == */
/* == window buttons == 28px touch targets, evenly spaced, in line with the header */
#moodtube-mini-player .mt-window-btn { width: 28px; height: 28px; min-width: 28px; padding: 0; box-sizing: border-box; display: flex; align-items: center; justify-content: center; line-height: 1; top: 6px; font-size: 14px; }
#moodtube-mini-player .mt-window-btn.mt-btn-close { right: 10px; left: auto; }
#moodtube-mini-player .mt-window-btn.mt-btn-settings { right: 42px; left: auto; }
#moodtube-mini-player .mt-window-btn.mt-btn-search { right: 74px; left: auto; }
#moodtube-mini-player .mt-window-btn.mt-btn-lyrics { right: 106px; left: auto; }
/* == /window buttons == */
